import React from "react";
import { MapPin, Star } from "lucide-react";
import Background from "../components/Background"; 
import "../styles/Marketplace.css";

const projectsData = [
  {
    id: 1,
    name: "Vinhomes Grand Park – TPHCM",
    type: "Căn hộ",
    hot: true,
    location: "Quận 9, TPHCM",
    rating: 4.9,
    reviews: 156,
    tags: ["Cao cấp", "Thông minh", "Tiện ích đầy đủ"],
    thumbnail: "/images/vinhomes.png",
  },
  {
    id: 2,
    name: "FLC Quy Nhon Beach & Golf Resort",
    type: "Resort",
    hot: true,
    location: "Quy Nhơn, Bình Định",
    rating: 4.7,
    reviews: 89,
    tags: ["Biển", "Golf", "Nghỉ dưỡng"],
    thumbnail: "/images/flc.png",
  },
  {
    id: 3,
    name: "Dalat Wonder Resort",
    type: "Resort",
    hot: false,
    location: "Đà Lạt, Lâm Đồng",
    rating: 4.8,
    reviews: 124,
    tags: ["Sinh thái", "Mát mẻ", "Tự nhiên"],
    thumbnail: "/images/dalat.png",
  },
];

const Marketplace = () => {
  return (
    <Background showShapes={false}fullWidth={true}>
      <div className="marketplace-container">
        <h1 className="marketplace-title">Dự Án Bất Động Sản Nổi Bật</h1>
        <p className="marketplace-subtitle">
          Khám phá những dự án bất động sản cao cấp và nổi bật trên khắp Việt Nam.
        </p>

        <div className="projects-grid">
          {projectsData.map((project) => (
            <div key={project.id} className="project-card">
              <div className="thumbnail-wrapper">
                <img
                  src={project.thumbnail}
                  alt={project.name}
                  className="thumbnail"
                />
                <span className="badge">{project.type}</span>
                {project.hot && <span className="hot">Hot</span>}
              </div>

              <div className="project-info">
                <h2 className="project-name">{project.name}</h2>
                <div className="location">
                  <MapPin size={16} /> {project.location}
                </div>
                <div className="rating">
                  <Star size={16} color="gold" /> {project.rating}
                  <span className="reviews">({project.reviews} đánh giá)</span>
                </div>

                <div className="tags">
                  {project.tags.map((tag, index) => (
                    <span key={index} className="tag">
                      {tag}
                    </span>
                  ))}
                </div>

                <div className="actions">
                  <button className="btn-outline">Xem trước</button>
                  <button className="btn-primary">Chi tiết</button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </Background>
  );
};

export default Marketplace;
